doc.codeblock:
export interface NoteItem {
  id: number;        // 单调自增正整数：1, 2, 3...
  content: string;   // 纯多行文本（统一 \n 换行）
  createdAt: number; // 创建时间戳 (ms)
  updatedAt: number; // 最后更新时间戳 (ms)
}

export interface NotesState {
  nextId: number;    // 初始为 1，恒 >= (max(items.id) + 1)，删除不复用
  items: NoteItem[];
}
